export interface Member {
  id: string;
  displayName: string;
  avatar: string | null;
}

export interface SessionState {
  member: Member | null;
  pending: boolean;
  revision: number;
}

export type SessionEvent =
  | { type: "begin" }
  | { type: "accept"; member: Member }
  | { type: "reject" }
  | { type: "clear" };

function copy(member: Member | null): Member | null {
  return member === null ? null : { ...member };
}

export function updateSession(state: SessionState, event: SessionEvent): SessionState {
  if (!event || typeof event !== "object" || typeof (event as { type?: unknown }).type !== "string") {
    throw new TypeError("Invalid session event");
  }
  const current = copy(state.member);
  switch (event.type) {
    case "begin": return { member: current, pending: true, revision: state.revision };
    case "reject": return { member: current, pending: false, revision: state.revision };
    case "clear": return { member: null, pending: false, revision: state.revision };
    case "accept": {
      const member = event.member;
      if (!member || typeof member.id !== "string" || member.id.length === 0 ||
          typeof member.displayName !== "string" || member.displayName.length === 0 ||
          (member.avatar !== null && typeof member.avatar !== "string")) {
        throw new TypeError("Invalid session event");
      }
      return { member: { ...member }, pending: false, revision: state.revision + 1 };
    }
    default: throw new TypeError("Invalid session event");
  }
}

