import { updateSession, type Member, type SessionEvent, type SessionState } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function invalid(state: SessionState, event: unknown, message: string): void {
  const before = JSON.stringify(state);
  try {
    updateSession(state, event as SessionEvent);
  } catch (error) {
    assert(error instanceof TypeError && error.message === 'Invalid session event', message);
    assert(JSON.stringify(state) === before, `${message}: state was mutated`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const originalMember: Member = { id: 'm1', displayName: 'Ada', avatar: null };
const state: SessionState = { member: originalMember, pending: false, revision: 4 };
const begun = updateSession(state, { type: 'begin' });
equal(begun, { member: originalMember, pending: true, revision: 4 }, 'begin changes only pending');
assert(begun !== state, 'begin returns a new state');
assert(begun.member !== originalMember, 'begin copies the current member');
assert(state.pending === false && state.revision === 4, 'begin does not mutate state');

const rejected = updateSession({ member: originalMember, pending: true, revision: 4 }, { type: 'reject' });
equal(rejected, { member: originalMember, pending: false, revision: 4 }, 'reject changes only pending');
assert(rejected.member !== originalMember, 'reject copies the preserved member');

const acceptedMember: Member = { id: 'm2', displayName: 'Grace', avatar: 'grace.png' };
const acceptEvent: SessionEvent = { type: 'accept', member: acceptedMember };
const accepted = updateSession(state, acceptEvent);
equal(accepted, { member: acceptedMember, pending: false, revision: 5 }, 'accept stores member and increments revision');
assert(accepted.member !== acceptedMember, 'accepted member does not alias event member');
assert(accepted.member !== originalMember, 'accepted member does not alias state member');
assert(acceptEvent.member === acceptedMember, 'accept does not replace event member');
assert(state.member === originalMember, 'accept does not replace state member');
accepted.member!.displayName = 'Changed';
assert(acceptedMember.displayName === 'Grace', 'returned member mutation does not affect event');

const cleared = updateSession({ member: originalMember, pending: true, revision: 9 }, { type: 'clear' });
equal(cleared, { member: null, pending: false, revision: 10 }, 'clear removes member and increments revision');
const emptyBegin = updateSession({ member: null, pending: false, revision: 0 }, { type: 'begin' });
equal(emptyBegin, { member: null, pending: true, revision: 0 }, 'begin preserves a null member');

invalid(state, null, 'rejects null event');
invalid(state, {}, 'rejects event without type');
invalid(state, { type: 'unknown' }, 'rejects unknown type');
invalid(state, { type: 'accept' }, 'rejects accept without member');
invalid(state, { type: 'accept', member: null }, 'rejects null accepted member');
invalid(state, { type: 'accept', member: { id: '', displayName: 'Name', avatar: null } }, 'rejects empty id');
invalid(state, { type: 'accept', member: { id: 'id', displayName: '', avatar: null } }, 'rejects empty display name');
invalid(state, { type: 'accept', member: { id: 'id', displayName: 'Name', avatar: 3 } }, 'rejects invalid avatar');
invalid(state, { type: 'accept', member: { id: 1, displayName: 'Name', avatar: null } }, 'rejects non-string id');

